		/** 
		 * Tests creating a new Seller.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Seller");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Seller" );

			try {            
				Seller entity = SellerService.getSellerInstance().createSeller( generateNewEntity() );
				thePrimaryKey = entity.getSellerId();
				LOGGER.info( "-- Successfully created a Seller with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Seller. 
		 */
		public Seller testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Seller" );

			Seller entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Seller with primary key" );
			msg.append( thePrimaryKey );
			
			SellerFetchOneSummary fetchOneSummary = new SellerFetchOneSummary( thePrimaryKey );

			try {
				entity = SellerService.getSellerInstance().getSeller( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Seller " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Seller.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Seller." );

			StringBuilder msg = new StringBuilder( "Failed to update a Seller : " );        
			Seller entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Seller." );

				// for use later on...
				thePrimaryKey = entity.getSellerId();

				SellerService proxy = SellerService.getSellerInstance();            
				proxy.updateSeller( entity );   

				LOGGER.info( "-- Successfully saved Seller - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Seller.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Seller." );

			try{
			    Seller entity = testRead(); 
				SellerService.getSellerInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Seller with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Seller with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Sellers.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Sellers:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Seller : " );        
			List<Seller> collection  = null;

			try {
				// call the static get method on the SellerService
				collection = SellerService.getSellerInstance().getAllSeller();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Seller entity = null;            
					Iterator<Seller> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getSellerId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

